    font-size: 11px;
}

/* Tab Styling */
.dashboard-tabs {
    background: white;
    border-radius: 10px 10px 0 0;
    margin-bottom: 0;
}

.nav-tabs {
    border-bottom: 1px solid #dee2e6;
    padding: 0;
}

.nav-tabs .nav-item {
    margin-bottom: -1px;
}

.nav-tabs .nav-link {
    border: 1px solid transparent;
    border-top-left-radius: 10px;
    border-top-right-radius: 10px;
    color: #495057;
    font-weight: 500;
    padding: 12px 20px;
    transition: color 0.15s ease-in-out, background-color 0.15s ease-in-out, border-color 0.15s ease-in-out;
}

.nav-tabs .nav-link:hover {
    border-color: #e9ecef #e9ecef #dee2e6;
    color: #3498db;
}

.nav-tabs .nav-link.active {
    color: #3498db;
    background-color: #fff;
    border-color: #dee2e6 #dee2e6 #fff;
    font-weight: 600;
}

.nav-tabs .nav-link i {
    margin-right: 8px;
}

.tab-content {
    border: 1px solid #dee2e6;
    border-top: none;
    border-radius: 0 0 10px 10px;
    padding: 20px;
    background: white;
}

.tab-pane {
    display: none;
}

.tab-pane.active {
    display: block;
}

/* Modal styles */
.modal {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0,0,0,0.5);
    z-index: 1000;
    justify-content: center;
    align-items: center;
}

.modal.show {
    display: flex;
}

.modal-content {
    background: white;
    border-radius: 10px;
    width: 90%;
    max-width: 500px;
    max-height: 90vh;
    overflow-y: auto;
}

.modal-dialog.modal-lg .modal-content {
    max-width: 800px;
}

.modal-header {
    padding: 20px;
    border-bottom: 1px solid #e1e8ed;
    display: flex;
    justify-content: space-between;
    align-items: center;
}

.modal-header h5 {
    margin: 0;
    color: #2c3e50;
}

.modal-body {
    padding: 20px;
}

.modal-footer {
    padding: 20px;
    border-top: 1px solid #e1e8ed;
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}

.close {
    background: none;
    border: none;
    font-size: 24px;
    color: #7f8c8d;
    cursor: pointer;
    padding: 0;
}

.close:hover {
    color: #2c3e50;
}

.form-group {
    margin-bottom: 15px;
}

.form-group label {
    display: block;
    margin-bottom: 5px;
    color: #2c3e50;
    font-weight: 500;
}

.form-control {
    width: 100%;
    padding: 10px;
    border: 1px solid #ddd;
    border-radius: 5px;
    font-size: 14px;
}

.form-control-range {
    width: 100%;
    margin: 10px 0;
}

#progressValue, #updateProgressValue {
    display: inline-block;
    margin-left: 10px;
    font-weight: bold;
    color: #3498db;
}

.tender-details-view .row {
    margin-bottom: 15px;
}

.tender-details-view strong {
    color: #2c3e50;
    font-weight: 600;
}

.tender-item-modal {
    background: #f8f9fa;
    padding: 10px;
    border-radius: 6px;
    margin-bottom: 10px;
}

.tender-item-modal .row {
    display: flex;
    align-items: center;
    margin-bottom: 5px;
}

.tender-item-modal .col {
    padding: 5px;
}

.tender-item-modal .description {
    color: #2c3e50;
    font-weight: 500;
}

.tender-item-modal .employee {
    color: #7f8c8d;
    font-size: 13px;
}

.tender-item-modal .status {
    font-size: 12px;
    padding: 2px 8px;
    border-radius: 12px;
}

/* Date styling */
.parent-task-dates,
.child-task-dates,
.task-dates,
.tender-dates {
    margin-top: 8px;
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
}

.parent-task-dates small,
.child-task-dates small,
.task-dates small,
.tender-dates small {
    color: #7f8c8d;
    font-size: 12px;
    display: flex;
    align-items: center;
    gap: 5px;
}

.parent-task-dates i,
.child-task-dates i,
.task-dates i,
.tender-dates i {
    font-size: 11px;
    opacity: 0.7;
}

/* Progress bar for tenders */
.progress-bar-tender {
    height: 6px;
    background: #e9ecef;
    border-radius: 3px;
    overflow: hidden;
}

.progress-fill-tender {
    height: 100%;
    border-radius: 3px;
    background: linear-gradient(90deg, #3498db, #2ecc71);
    transition: width 0.3s ease;
}

/* Responsive adjustments */
@media (max-width: 768px) {
    .dashboard-header {
        flex-direction: column;
        gap: 15px;
        text-align: center;
    }

    .project-filter, .tender-filter {
        flex-direction: column;
    }

    .parent-task-main {
        flex-direction: column;
        gap: 10px;
    }

    .parent-task-details {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .parent-task-progress {
        max-width: 100%;
        width: 100%;
    }

    .child-task-content {
        flex-direction: column;
    }

    .child-task-indicator {
        border-right: none;
        border-bottom: 2px solid #e1e8ed;
        padding-right: 0;
        padding-bottom: 10px;
        margin-right: 0;
        margin-bottom: 10px;
    }

    .child-task-body {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .child-task-progress {
        max-width: 100%;
        width: 100%;
    }

    .independent-task-body {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .independent-task-body .task-progress {
        max-width: 100%;
        width: 100%;
    }

    .tender-item-row {
        flex-direction: column;
        align-items: flex-start;
        gap: 10px;
    }

    .tender-item-progress {
        max-width: 100%;
        width: 100%;
    }

    .tender-header {
        flex-direction: column;
        gap: 10px;
    }

    .tender-status {
        align-self: flex-start;
    }

    .nav-tabs .nav-link {
        padding: 10px 15px;
        font-size: 14px;
    }

    .modal-content {
        width: 95%;
        margin: 10px;
    }

    .tender-item-modal .row {
        flex-direction: column;
        align-items: flex-start;
    }
}

@media (max-width: 576px) {
    .dashboard-stats {
        grid-template-columns: 1fr;
    }

    .parent-task-dates,
    .child-task-dates,
    .task-dates,
    .tender-dates {
        flex-direction: column;
        gap: 5px;
    }

    .parent-task-dates small,
    .child-task-dates small,
    .task-dates small,
    .tender-dates small {
        margin-left: 0 !important;
    }
}

.searchable-dropdown {
    position: relative;
    flex: 1;
}

.searchable-input {
    padding-right: 30px; 
}

.searchable-clear-btn {
    position: absolute;
    right: 8px;
    top: 50%;
    transform: translateY(-50%);
    background: none;
    border: none;
    font-size: 18px;
    line-height: 1;
    color: #95a5a6;
    cursor: pointer;
    padding: 2px 4px;
    z-index: 5;
}

.searchable-clear-btn:hover {
    color: #e74c3c;
}
